function applyRumboScene(){
 const tz=Intl.DateTimeFormat().resolvedOptions().timeZone||"";
 const hour=Number(new Intl.DateTimeFormat("en-GB",{hour:"2-digit",hourCycle:"h23"}).format(new Date()));
 const country=visualPrefs.country==="auto"?localCountry():visualPrefs.country;
 const light=visualPrefs.light==="auto"?(hour>=6&&hour<18?"day":"night"):visualPrefs.light;
 document.body.dataset.rumboTheme=light;document.body.dataset.rumboCountry=country;
 const bg=document.getElementById("rumbo-scene-bg");if(bg){bg.innerHTML=sceneSvg(country,light==="day");bg.setAttribute("aria-label",sceneNames[country]||"Country skyline");const landmark=bg.querySelector(".rumbo-scene-landmark"),overlay=document.getElementById("rumbo-scene-overlay");if(overlay&&landmark){overlay.innerHTML=landmark.outerHTML;landmark.remove()}}
 const countrySelect=document.getElementById("rumboCountry"),lightSelect=document.getElementById("rumboLightMode"),citySelect=document.getElementById("rumboCity");
 if(countrySelect)countrySelect.value=visualPrefs.country;if(lightSelect)lightSelect.value=visualPrefs.light;
 if(citySelect){const selected=localStorage.getItem(CITY_KEY)||"auto";citySelect.value=selected;const latest=(state.logbook||[]).filter(x=>x.date&&x.to).sort((a,b)=>b.date.localeCompare(a.date))[0],lastCity=latest?cityForAirport(latest.to)?.[0]:null;loadCityScene(selected==="auto"?(lastCity||"Doha"):selected,light==="day")}
 document.documentElement.style.colorScheme=light==="day"?"light":"dark";
}
async function loadCityScene(city,day){
 const bg=document.getElementById("rumbo-scene-bg");if(!bg)return;
 const request=++citySceneRequest,key=city+"|"+(day?"day":"night"),page=cityCatalogue().find(x=>x.city===city)?.page||city;let data=citySceneCache.get(key);
 if(!data){try{const response=await fetch("https://en.wikipedia.org/api/rest_v1/page/summary/"+encodeURIComponent(page),{headers:{accept:"application/json"},cache:"force-cache"});if(!response.ok)throw new Error("City image unavailable");const json=await response.json();data={image:json.originalimage?.source||json.thumbnail?.source||"",description:json.description||json.title||city};citySceneCache.set(key,data)}catch(e){data={image:"",description:city};citySceneCache.set(key,data)}}
 if(request!==citySceneRequest)return;
 if(data.image){bg.innerHTML='<div class="rumbo-city-scene"><img class="rumbo-city-photo" src="'+data.image+'" alt="'+city+' city background" loading="eager"><div class="rumbo-city-grade"></div><div class="rumbo-city-caption">'+city.toUpperCase()+' · '+data.description.toUpperCase()+'</div></div>';bg.setAttribute("aria-label",city+" city scene")}
}
function initRumboScene(){
 const country=document.getElementById("rumboCountry"),light=document.getElementById("rumboLightMode"),city=document.getElementById("rumboCity");
 if(city){const entries=cityCatalogue();city.innerHTML='<option value="auto">Auto · last destination</option>'+entries.map(x=>'<option value="'+x.city.replace(/"/g,"&quot;")+'">'+x.city+' · '+x.country+'</option>').join("");city.value=localStorage.getItem(CITY_KEY)||"auto";city.onchange=()=>{localStorage.setItem(CITY_KEY,city.value);applyRumboScene()}}
 if(country)country.onchange=()=>{visualPrefs.country=country.value;localStorage.setItem(VISUAL_KEY,JSON.stringify(visualPrefs));applyRumboScene()};
 if(light)light.onchange=()=>{visualPrefs.light=light.value;localStorage.setItem(VISUAL_KEY,JSON.stringify(visualPrefs));applyRumboScene()};
 applyRumboScene();setInterval(()=>{if(visualPrefs.light==="auto"||visualPrefs.country==="auto")applyRumboScene()},60000);
 document.addEventListener("visibilitychange",()=>{if(!document.hidden)applyRumboScene()});
}

function emptyState(){return {duties:[],reminders:[],events:[],workouts:[],shopping:[],expenses:[],logbook:[],recommendations:[],mealPlan:[],pantry:[],budgets:{},trainingPlan:[],trainingGoals:[],aviationTraining:[],aiLog:[],rosterHotels:[],rosterTraining:[],airportNotes:[]}}
function normalizeState(raw){const base=emptyState(),source=raw&&typeof raw==="object"&&!Array.isArray(raw)?raw:{};const next={...base,...source};for(const key of ["duties","reminders","events","workouts","shopping","expenses","logbook","recommendations","mealPlan","pantry","trainingPlan","trainingGoals","aviationTraining","aiLog","rosterHotels","rosterTraining","airportNotes"])if(!Array.isArray(next[key]))next[key]=[];if(!next.budgets||typeof next.budgets!=="object"||Array.isArray(next.budgets))next.budgets={};return next}
function load(){try{return normalizeState(JSON.parse(localStorage.getItem(KEY)||"null"))}catch{return emptyState()}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(x=""){return String(x).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(s){let t=$("#toast");t.textContent=s;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2400)}
function nav(){const html=modules.map(([id,n])=>`<button class="nav-btn ${id===active?"active":""}" data-go="${id}"><b class="ico">${icons[id]}</b><span>${n}</span></button>`).join("");$("#nav").innerHTML=html;$("#mobileNav").innerHTML=modules.map(([id,n])=>'<button data-go="'+id+'" class="'+(id===active?"active":"")+'" aria-label="'+n+'" title="'+n+'"><b>'+icons[id]+'</b><span>'+({home:"Command",roster:"Roster",aviation:"Aviation",training:"Training",nutrition:"Nutrition",family:"Family",finance:"Finance",ai:"RUMBO AI"}[id])+'</span></button>').join("");document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>{active=b.dataset.go;render()})}
function head(k,title,desc,action=""){return `<div class="page-head"><div><div class="kicker">${k}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function panel(title,body,extra=""){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div>${body}</section>`}
function metric(label,value){return `<section class="panel"><div class="stat-label">${label}</div><div class="stat">${value}</div></section>`}
function dateText(d){return new Date(d+"T12:00:00").toLocaleDateString("es-ES",{day:"2-digit",month:"short"})}
function modeFamilyShift(key,mode,direction){const d=new Date(key+"T12:00:00");if(mode==="week")d.setDate(d.getDate()+direction*7);else d.setMonth(d.getMonth()+direction);return dateKey(d)}
function dateKey(d){return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function shiftDate(key,days){const d=new Date(key+"T12:00:00");d.setDate(d.getDate()+days);return dateKey(d)}
function weekStart(key){const d=new Date(key+"T12:00:00");d.setDate(d.getDate()-d.getDay());return dateKey(d)}
function dayEvents(date){
 const school=sekSchoolCalendar2026_27.filter(x=>x.date===date);
 const lessons=schoolLessonsForDate(date);
 const duties=state.duties.filter(x=>x.date===date);
 const events=state.events.filter(x=>x.date===date);
 const reminders=expandReminders(state.reminders||[],date,date);
 return {school,lessons,duties,events,reminders};
}
function rosterType(x){
 const raw=[x.code,x.kind,x.status,x.raw,x.type].filter(Boolean).join(" ").toUpperCase();
 if(/\b(PSBY|STANDBY|STAND-BY|SBY)\b/.test(raw))return "STANDBY";
 if(/\b(OFF|DOFF|DAY OFF|REST)\b/.test(raw))return "OFF";
 if(/\b(GRND|GROUND|TRAINING|SIM|SIMULATOR|TRNG|TRG)\b/.test(raw))return "TRAINING";
 if(/\b(LEAVE|VAC|VACATION|ANNUAL LEAVE|AL)\b/.test(raw))return "LEAVE";
 if(/FLIGHT|DUTY|\d{3,4}/.test(raw)||x.segments?.length)return "FLIGHT";
 return "OTHER";
}
function monthRosterSummary(duties,key){
 const list=duties.filter(x=>String(x.date||"").startsWith(key)),byDate=new Map(),priority={FLIGHT:6,TRAINING:5,STANDBY:4,LEAVE:3,OFF:2,OTHER:1};
 for(const x of list){const type=rosterType(x),current=byDate.get(x.date);if(!current||(priority[type]||0)>(priority[current]||0))byDate.set(x.date,type)}
 const out={FLIGHT:0,OFF:0,STANDBY:0,TRAINING:0,LEAVE:0,OTHER:0};
 for(const type of byDate.values())out[type]++;
 return {...out,entries:list.length,days:byDate.size};
}
