 const aircraft=[...aircraftMap.values()].sort((a,b)=>b.hours-a.hours),maxAircraft=Math.max(1,...aircraft.map(x=>x.hours)),maxMonth=Math.max(1,...stats.monthly.map(x=>x.hours));
