 const monthKey=today().slice(0,7),month=monthRosterSummary(state.duties,monthKey),monthSectors=state.logbook.filter(x=>String(x.date||"").startsWith(monthKey)),monthHours=monthSectors.reduce((n,x)=>n+Number(x.hours||0),0);
