 const insights=[];
 if(expiring)insights.push({level:expiringRecords.some(x=>x.expiry<today())?"urgent":"attention",title:"Training validity review",detail:expiringRecords.length+" record(s) expired or due within 90 days. First: "+expiringRecords[0].title+" · "+dateText(expiringRecords[0].expiry),target:"training"});
